parameters.text:
=Analiza la siguiente interacción de la comunidad:

ID: {{ $json.id }}
Autor: {{ $json.autor }}
Canal: {{ $json.canal }}
Tipo Original: {{ $json.tipo }}
Texto del mensaje:
"{{ $json.texto }}"

parameters.inputSchema:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "CommunityLabAssetOutput",
  "type": "object",
  "properties": {
    "sentimiento": {
      "type": "string",
      "enum": ["positivo", "neutro", "negativo"],
      "description": "Sentimiento del mensaje"
    },
    "tipo_contenido": {
      "type": "string",
      "enum": ["logro_contratacion", "duda_tecnica", "feedback_general", "showcase"],
      "description": "Categoría de contenido identificada"
    },
    "temas_clave": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Lista de tecnologías o conceptos clave identificados"
    },
    "post_linkedin": {
      "type": ["string", "null"],
      "description": "Copy optimizado para LinkedIn si aplica, de lo contrario null"
    },
    "tip_tecnico_faq": {
      "type": ["string", "null"],
      "description": "Respuesta técnica estructurada o FAQ si aplica, de lo contrario null"
    }
  },
  "required": [
    "sentimiento",
    "tipo_contenido",
    "temas_clave",
    "post_linkedin",
    "tip_tecnico_faq"
  ]
}

parameters.jsCode:
// Nodo de consolidación: Recopila todos los items enrutados y genera los 4 paquetes especializados para OCI
const allItems = $input.all().map(item => item.json);
const total = allItems.length;
const hoy = new Date().toISOString();

// Cálculo de métricas de sentimiento
const sentimientos = {
  positivo: allItems.filter(i => i.sentimiento === 'positivo').length,
  neutro: allItems.filter(i => i.sentimiento === 'neutro').length,
  negativo: allItems.filter(i => i.sentimiento === 'negativo').length
};

const distribucion_tipo = {
  logro_contratacion: allItems.filter(i => i.tipo_contenido === 'logro_contratacion').length,
  duda_tecnica: allItems.filter(i => i.tipo_contenido === 'duda_tecnica').length,
  showcase: allItems.filter(i => i.tipo_contenido === 'showcase').length,
  feedback_general: allItems.filter(i => i.tipo_contenido === 'feedback_general').length
};

const baseMetadata = {
  version: '1.0.0',
  plataforma: 'CommunityLab',
  fecha_generacion: hoy,
  origen_comunidad: 'Discord_Oracle_Next_Education_G10',
  total_interacciones: total
};

// 1. Rama A: Logros / Contrataciones
const paqueteLogros = {
  metadata: { ...baseMetadata, categoria: 'logros_contratacion' },
  activos: allItems
    .filter(i => i.tipo_contenido === 'logro_contratacion' && i.post_linkedin)
    .map(i => ({
      id: i.id,
      autor: i.autor,
      canal: i.canal,
      temas_clave: i.temas_clave,
      post_linkedin: i.post_linkedin
    }))
};

// 2. Rama B: Dudas Técnicas / FAQs
const paqueteFaqs = {
  metadata: { ...baseMetadata, categoria: 'dudas_tecnicas_faqs' },
  activos: allItems
    .filter(i => i.tipo_contenido === 'duda_tecnica' && i.tip_tecnico_faq)
    .map(i => ({
      id: i.id,
      autor: i.autor,
      canal: i.canal,
      temas_clave: i.temas_clave,
      pregunta_original: i.texto_original,
      tip_tecnico_faq: i.tip_tecnico_faq
    }))
};

// 3. Rama C: Showcase de Proyectos
const paqueteShowcase = {
  metadata: { ...baseMetadata, categoria: 'proyectos_showcase' },
  activos: allItems
    .filter(i => i.tipo_contenido === 'showcase' && i.post_linkedin)
    .map(i => ({
      id: i.id,
      autor: i.autor,
      canal: i.canal,
      temas_clave: i.temas_clave,
      post_linkedin: i.post_linkedin
    }))
};

// 4. Rama D: Feedback y Métricas de Comunidad
const paqueteFeedback = {
  metadata: { ...baseMetadata, categoria: 'feedback_metricas' },
  metricas_salud: { sentimientos, distribucion_tipo },
  activos: allItems
    .filter(i => i.tipo_contenido === 'feedback_general')
    .map(i => ({
      id: i.id,
      autor: i.autor,
      canal: i.canal,
      temas_clave: i.temas_clave,
      comentario: i.texto_original,
      sentimiento: i.sentimiento
    }))
};

// Emitir 4 items separados, cada uno con su nombre de archivo OCI
return [
  { json: { nombre_archivo: 'marketing_linkedin_logros.json', ...paqueteLogros } },
  { json: { nombre_archivo: 'faqs_soporte_tecnico.json', ...paqueteFaqs } },
  { json: { nombre_archivo: 'marketing_showcase.json', ...paqueteShowcase } },
  { json: { nombre_archivo: 'metricas_feedback_comunidad.json', ...paqueteFeedback } }
];

// Extrae las interacciones recibidas desde la UI de Streamlit o petición HTTP
const body = $json.body || $json;
const items = body.interacciones || body.data || (Array.isArray(body) ? body : [body]);

if (!items || items.length === 0) {
  throw new Error('No se recibieron interacciones en el body de la petición');
}

return items.map(item => ({ json: item }));

const itemsProcesados = $('Loop Over Items1').all();
const archivosSubidos = $('Upload a file1').all();

const postsCount = itemsProcesados.filter(i => i.json?.post_linkedin).length;
const tipsCount = itemsProcesados.filter(i => i.json?.tip_tecnico_faq).length;

const sentimientoDist = {
  positivo: itemsProcesados.filter(i => i.json?.sentimiento === 'positivo').length,
  neutro: itemsProcesados.filter(i => i.json?.sentimiento === 'neutro').length,
  negativo: itemsProcesados.filter(i => i.json?.sentimiento === 'negativo').length
};

const activos = itemsProcesados.map(item => ({
  interaccion: {
    id: item.json?.id || "N/A",
    autor: item.json?.autor || "Comunidad",
    canal: item.json?.canal || "#general",
    texto: item.json?.comentario || item.json?.pregunta_original || item.json?.post_linkedin || ""
  },
  activo: {
    tipo_contenido: item.json?.tipo_contenido || "feedback_general",
    sentimiento: item.json?.sentimiento || "neutro",
    temas_clave: item.json?.temas_clave || [],
    post_linkedin: item.json?.post_linkedin || null,
    tip_tecnico_faq: item.json?.tip_tecnico_faq || null
  },
  motor_orquestacion: "n8n_oci_cloud"
}));

return [{
  json: {
    status: "completado",
    metadata_paquete: {
      motor_orquestacion: "n8n_oci_cloud",
      total_procesados_exitosamente: itemsProcesados.length,
      total_archivos_oci: archivosSubidos.length
    },
    metricas: {
      total_posts_linkedin_generados: postsCount,
      total_tips_faq_generados: tipsCount,
      distribucion_sentimiento: sentimientoDist
    },
    activos: activos
  }
}];
